queries.sphinxql:

create table t (title text, n int chunk_strategy='sentence');
create table t (title text, v float_vector_array chunk_strategy='sentence');
create table t (title text, v float_vector_array knn_type='hnsw' knn_dims='4' hnsw_similarity='l2' chunk_strategy='sentence');
create table t (title text, v float_vector_array knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' max_tokens='128');
create table t (title text, v float_vector_array knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='truncate' max_tokens='128');
create table t (title text, v float_vector knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='sentence' max_tokens='128');
create table t (title text, v float_vector_array knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='fixed' overlap_tokens='16');
create table t (title text, v float_vector_array knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='fixed' max_tokens='0' overlap_tokens='16');
create table t (title text, v float_vector_array knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='paragraph');
create table t (title text, v float_vector_array knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='fixed' max_tokens='abc');
create table t (title text, v float_vector_array knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='fixed' max_tokens='-1');


create table t (title text, v float_vector_array knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='fixed' max_tokens='100' overlap_tokens='50');
show create table t;
drop table t;


create table t (title text, v float_vector knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='mean');
show create table t;
drop table t;


create table t (title text, v float_vector_array knn_type='hnsw' hnsw_similarity='cosine' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='sentence' max_tokens='64' overlap_tokens='8' max_chunks='16');
show create table t;
insert into t (id, title) values (1, 'The cat sat on the mat. Dogs bark loudly at night. Ships cross the ocean slowly.');
insert into t (id, title) values (2, 'One short sentence.');
insert into t (id, title, v) values (3, 'Explicitly empty vector', ());
select id from t where knn(v, 5, 'a dog barking') order by id asc;
flush ramchunk t;
select id from t where knn(v, 5, 'a dog barking') order by id asc;

show create table t;
select id from t where knn(v, 5, 'a dog barking') order by id asc;
drop table t;


create table t (title text, n int);
insert into t values (1, 'some text', 7);
alter table t add column v float_vector_array knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title';

alter table t add column s float_vector knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='mean';
show create table t;
select id from t where knn(s, 5, 'some text');

alter table t rebuild embeddings s;
select id from t where knn(s, 5, 'some text');
drop table t;


create table t (title text, v float_vector_array knn_type='hnsw' hnsw_similarity='l2' model_name='sentence-transformers/all-MiniLM-L6-v2' from='title' chunk_strategy='mean');
insert into t values (1, 'some text', ());
alter table t rebuild embeddings v;
drop table t;
